  echo "plan,signups,unique_users"
  for f in "$dir"/*.jsonl "$dir"/*.jsonl.gz; do [ -e "$f" ] && zcat -f "$f"; done \
    | jq -rs '[.[] | select(.type == "signup")] | unique_by(.event_id) | group_by(.account.plan // .plan) | map({p: (.[0].account.plan // .[0].plan), n: length, u: (map(.user.id // .user_id) | unique | length)}) | sort_by(-.n, .p) | .[] | "\(.p),\(.n),\(.u)"'
} > "$out"
EOF
